macro_rules! deps {
    () => {
        Lazy!();
        HalfMatch!();
        Cache!();
        Start!();
        Match!();
        Input!();
        CacheError!();
        DFA!();
        MatchError!();
    };
}

macro_rules! LazyStateID {
    () => {
        deps!();
        # [doc = " A state identifier specifically tailored for lazy DFAs."] # [doc = ""] # [doc = " A lazy state ID logically represents a pointer to a DFA state. In practice,"] # [doc = " by limiting the number of DFA states it can address, it reserves some"] # [doc = " bits of its representation to encode some additional information. That"] # [doc = " additional information is called a \"tag.\" That tag is used to record"] # [doc = " whether the state it points to is an unknown, dead, quit, start or match"] # [doc = " state."] # [doc = ""] # [doc = " When implementing a low level search routine with a lazy DFA, it is"] # [doc = " necessary to query the type of the current state to know what to do:"] # [doc = ""] # [doc = " * **Unknown** - The state has not yet been computed. The"] # [doc = " parameters used to get this state ID must be re-passed to"] # [doc = " [`DFA::next_state`](crate::hybrid::dfa::DFA::next_state), which will never"] # [doc = " return an unknown state ID."] # [doc = " * **Dead** - A dead state only has transitions to itself. It indicates that"] # [doc = " the search cannot do anything else and should stop with whatever result it"] # [doc = " has."] # [doc = " * **Quit** - A quit state indicates that the automaton could not answer"] # [doc = " whether a match exists or not. Correct search implementations must return a"] # [doc = " [`MatchError::quit`](crate::MatchError::quit) when a DFA enters a quit"] # [doc = " state."] # [doc = " * **Start** - A start state is a state in which a search can begin."] # [doc = " Lazy DFAs usually have more than one start state. Branching on"] # [doc = " this isn't required for correctness, but a common optimization is"] # [doc = " to run a prefilter when a search enters a start state. Note that"] # [doc = " start states are *not* tagged automatically, and one must enable the"] # [doc = " [`Config::specialize_start_states`](crate::hybrid::dfa::Config::specialize_start_states)"] # [doc = " setting for start states to be tagged. The reason for this is"] # [doc = " that a DFA search loop is usually written to execute a prefilter once it"] # [doc = " enters a start state. But if there is no prefilter, this handling can be"] # [doc = " quite disastrous as the DFA may ping-pong between the special handling code"] # [doc = " and a possible optimized hot path for handling untagged states. When start"] # [doc = " states aren't specialized, then they are untagged and remain in the hot"] # [doc = " path."] # [doc = " * **Match** - A match state indicates that a match has been found."] # [doc = " Depending on the semantics of your search implementation, it may either"] # [doc = " continue until the end of the haystack or a dead state, or it might quit"] # [doc = " and return the match immediately."] # [doc = ""] # [doc = " As an optimization, the [`is_tagged`](LazyStateID::is_tagged) predicate"] # [doc = " can be used to determine if a tag exists at all. This is useful to avoid"] # [doc = " branching on all of the above types for every byte searched."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how `LazyStateID` can be used to implement a correct"] # [doc = " search routine with minimal branching. In particular, this search routine"] # [doc = " implements \"leftmost\" matching, which means that it doesn't immediately"] # [doc = " stop once a match is found. Instead, it continues until it reaches a dead"] # [doc = " state."] # [doc = ""] # [doc = " Notice also how a correct search implementation deals with"] # [doc = " [`CacheError`](crate::hybrid::CacheError)s returned by some of"] # [doc = " the lazy DFA routines. When a `CacheError` occurs, it returns"] # [doc = " [`MatchError::gave_up`](crate::MatchError::gave_up)."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     hybrid::dfa::{Cache, DFA},"] # [doc = "     HalfMatch, MatchError, Input,"] # [doc = " };"] # [doc = ""] # [doc = " fn find_leftmost_first("] # [doc = "     dfa: &DFA,"] # [doc = "     cache: &mut Cache,"] # [doc = "     haystack: &[u8],"] # [doc = " ) -> Result<Option<HalfMatch>, MatchError> {"] # [doc = "     // The start state is determined by inspecting the position and the"] # [doc = "     // initial bytes of the haystack. Note that start states can never"] # [doc = "     // be match states (since DFAs in this crate delay matches by 1"] # [doc = "     // byte), so we don't need to check if the start state is a match."] # [doc = "     let mut sid = dfa.start_state_forward("] # [doc = "         cache,"] # [doc = "         &Input::new(haystack),"] # [doc = "     )?;"] # [doc = "     let mut last_match = None;"] # [doc = "     // Walk all the bytes in the haystack. We can quit early if we see"] # [doc = "     // a dead or a quit state. The former means the automaton will"] # [doc = "     // never transition to any other state. The latter means that the"] # [doc = "     // automaton entered a condition in which its search failed."] # [doc = "     for (i, &b) in haystack.iter().enumerate() {"] # [doc = "         sid = dfa"] # [doc = "             .next_state(cache, sid, b)"] # [doc = "             .map_err(|_| MatchError::gave_up(i))?;"] # [doc = "         if sid.is_tagged() {"] # [doc = "             if sid.is_match() {"] # [doc = "                 last_match = Some(HalfMatch::new("] # [doc = "                     dfa.match_pattern(cache, sid, 0),"] # [doc = "                     i,"] # [doc = "                 ));"] # [doc = "             } else if sid.is_dead() {"] # [doc = "                 return Ok(last_match);"] # [doc = "             } else if sid.is_quit() {"] # [doc = "                 // It is possible to enter into a quit state after"] # [doc = "                 // observing a match has occurred. In that case, we"] # [doc = "                 // should return the match instead of an error."] # [doc = "                 if last_match.is_some() {"] # [doc = "                     return Ok(last_match);"] # [doc = "                 }"] # [doc = "                 return Err(MatchError::quit(b, i));"] # [doc = "             }"] # [doc = "             // Implementors may also want to check for start states and"] # [doc = "             // handle them differently for performance reasons. But it is"] # [doc = "             // not necessary for correctness. Note that in order to check"] # [doc = "             // for start states, you'll need to enable the"] # [doc = "             // 'specialize_start_states' config knob, otherwise start"] # [doc = "             // states will not be tagged."] # [doc = "         }"] # [doc = "     }"] # [doc = "     // Matches are always delayed by 1 byte, so we must explicitly walk"] # [doc = "     // the special \"EOI\" transition at the end of the search."] # [doc = "     sid = dfa"] # [doc = "         .next_eoi_state(cache, sid)"] # [doc = "         .map_err(|_| MatchError::gave_up(haystack.len()))?;"] # [doc = "     if sid.is_match() {"] # [doc = "         last_match = Some(HalfMatch::new("] # [doc = "             dfa.match_pattern(cache, sid, 0),"] # [doc = "             haystack.len(),"] # [doc = "         ));"] # [doc = "     }"] # [doc = "     Ok(last_match)"] # [doc = " }"] # [doc = ""] # [doc = " // We use a greedy '+' operator to show how the search doesn't just stop"] # [doc = " // once a match is detected. It continues extending the match. Using"] # [doc = " // '[a-z]+?' would also work as expected and stop the search early."] # [doc = " // Greediness is built into the automaton."] # [doc = " let dfa = DFA::new(r\"[a-z]+\")?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = " let haystack = \"123 foobar 4567\".as_bytes();"] # [doc = " let mat = find_leftmost_first(&dfa, &mut cache, haystack)?.unwrap();"] # [doc = " assert_eq!(mat.pattern().as_usize(), 0);"] # [doc = " assert_eq!(mat.offset(), 10);"] # [doc = ""] # [doc = " // Here's another example that tests our handling of the special"] # [doc = " // EOI transition. This will fail to find a match if we don't call"] # [doc = " // 'next_eoi_state' at the end of the search since the match isn't found"] # [doc = " // until the final byte in the haystack."] # [doc = " let dfa = DFA::new(r\"[0-9]{4}\")?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = " let haystack = \"123 foobar 4567\".as_bytes();"] # [doc = " let mat = find_leftmost_first(&dfa, &mut cache, haystack)?.unwrap();"] # [doc = " assert_eq!(mat.pattern().as_usize(), 0);"] # [doc = " assert_eq!(mat.offset(), 15);"] # [doc = ""] # [doc = " // And note that our search implementation above automatically works"] # [doc = " // with multi-DFAs. Namely, `dfa.match_pattern(match_state, 0)` selects"] # [doc = " // the appropriate pattern ID for us."] # [doc = " let dfa = DFA::new_many(&[r\"[a-z]+\", r\"[0-9]+\"])?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = " let haystack = \"123 foobar 4567\".as_bytes();"] # [doc = " let mat = find_leftmost_first(&dfa, &mut cache, haystack)?.unwrap();"] # [doc = " assert_eq!(mat.pattern().as_usize(), 1);"] # [doc = " assert_eq!(mat.offset(), 3);"] # [doc = " let mat = find_leftmost_first(&dfa, &mut cache, &haystack[3..])?.unwrap();"] # [doc = " assert_eq!(mat.pattern().as_usize(), 0);"] # [doc = " assert_eq!(mat.offset(), 7);"] # [doc = " let mat = find_leftmost_first(&dfa, &mut cache, &haystack[10..])?.unwrap();"] # [doc = " assert_eq!(mat.pattern().as_usize(), 1);"] # [doc = " assert_eq!(mat.offset(), 5);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Clone , Copy , Debug , Default , Eq , Hash , PartialEq , PartialOrd , Ord ,)] pub struct LazyStateID (u32) ;
    };
}

LazyStateID!();